'use client'

import { useStrings, type StringsOverrides } from './strings'
import * as React from 'react'
import './loading.css'
import './gamestage-primitives.css'

/**
 * Loading: the state a player sees while the game is being fetched, drawn
 * rather than written. GSUI-282, with Gamestage GS-537.
 *
 * Tom, 2026-09-27: the smoothest possible loading, a spinner or a bar rather
 * than text, nicely centred. So this fills its container and centres one
 * mark in it. The words are for screen readers only; a sighted player sees a
 * spinner, or a bar when the host knows how far through it is.
 *
 * It holds its container's size, so the game that replaces it arrives in one
 * step rather than jumping in. Reduced motion turns the spin into a slow pulse.
 * Page-level first paint, before any script runs, is the host's HTML's job
 * (Gamestage's scaffolds draw the same mark there); this is the same state for
 * everything after the scripts have started.
 */
export interface LoadingProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** `spinner` when there is no measure of progress, `bar` when there is. Default `spinner`. */
  variant?: 'spinner' | 'bar'
  /** For `bar`: how far through, 0 to 1. Absent draws a bar that sweeps. */
  value?: number
  /**
   * Draw the Gamestage loader rather than a bare mark: the chopstick-rest drawing
   * floating, "Made with Gamestage, by Monterosa", and a sweeping track, which is
   * Stage's own loader (GSUI-297). `true` uses the canon drawing from
   * gamestage.ai; pass `{ markSrc }` for a copy the game serves itself. The
   * words are `loading.poweredBy`, so a game can replace them, and an empty
   * string leaves the mark and the track alone.
   */
  brand?: boolean | { markSrc?: string }
  /** The words for this instance. */
  strings?: StringsOverrides
}

/** The canon Gamestage mark, the ink chopstick rest. */
export const GAMESTAGE_MARK_SRC = 'https://gamestage.ai/ink/chopsticks-rest.png'

export function Loading({ variant = 'spinner', value, brand, strings, className, ...rest }: LoadingProps) {
  const copy = useStrings(strings)
  if (brand) {
    const markSrc = (typeof brand === 'object' && brand.markSrc) || GAMESTAGE_MARK_SRC
    const powered = copy['loading.poweredBy']
    return (
      <div
        {...rest}
        className={['gs-loading', className].filter(Boolean).join(' ')}
        data-gs-component="loading"
        data-gs-loading="brand"
        role="status"
        aria-busy="true"
      >
        <div className="gs-loading__brand" data-gs-scope="loading" data-gs-part="brand">
          {/* A mask tinted with the theme's ink, so the black ink drawing reads on
              a dark theme as well as a light one. The canon file is served with
              open CORS, which a mask from another origin needs. */}
          <span
            className="gs-loading__mark"
            data-gs-scope="loading"
            data-gs-part="logo"
            aria-hidden="true"
            style={{ '--gs-loading-mark': `url("${markSrc}")` } as React.CSSProperties}
          />
          {powered ? (
            <span className="gs-loading__powered" data-gs-scope="loading" data-gs-part="note">
              {powered}
            </span>
          ) : null}
          <span className="gs-loading__track" data-gs-scope="loading" data-gs-part="track" aria-hidden="true">
            <span className="gs-loading__fill" data-gs-scope="loading" data-gs-part="fill" />
          </span>
        </div>
        <span className="gs-loading__label" data-gs-scope="loading" data-gs-part="label">
          {copy['loading.label']}
        </span>
      </div>
    )
  }
  const known = variant === 'bar' && typeof value === 'number' && Number.isFinite(value)
  const fraction = known ? Math.min(1, Math.max(0, value as number)) : undefined
  const percent = fraction === undefined ? undefined : Math.round(fraction * 100)
  return (
    <div
      {...rest}
      className={['gs-loading', className].filter(Boolean).join(' ')}
      data-gs-component="loading"
      data-gs-loading={variant}
      role="status"
      aria-busy="true"
    >
      {variant === 'bar' ? (
        <div
          className="gs-loading__track"
          data-gs-scope="loading"
          data-gs-part="track"
          role="progressbar"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={percent}
          aria-label={percent === undefined ? copy['loading.label'] : copy['loading.progress'](percent)}
          style={fraction === undefined ? undefined : ({ '--gs-loading-fraction': String(fraction) } as React.CSSProperties)}
        >
          <span className="gs-loading__fill" data-gs-scope="loading" data-gs-part="fill" />
        </div>
      ) : (
        <span className="gs-loading__spinner" data-gs-scope="loading" data-gs-part="spinner" aria-hidden="true" />
      )}
      <span className="gs-loading__label" data-gs-scope="loading" data-gs-part="label">
        {percent === undefined ? copy['loading.label'] : copy['loading.progress'](percent)}
      </span>
    </div>
  )
}

export interface GamestageLoaderProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * False while the game is getting ready; true once its first screen is drawn
   * underneath. The loader then fades and leaves the page. Default false.
   */
  ready?: boolean
  /** The mark, as for `Loading`'s `brand`: `true` for the canon drawing. */
  brand?: LoadingProps['brand']
  /** The words for this instance. */
  strings?: StringsOverrides
}

/** How long the fade takes, in ms. Matches the CSS transition. */
const LEAVE_MS = 200

/**
 * GamestageLoader: the default loader for a Gamestage game. Tom, 2026-09-30,
 * from Mystery | Premier League.
 *
 *     const [ready, setReady] = React.useState(false)
 *     return <>
 *       <GamestageLoader ready={ready} />
 *       <Game onFirstRound={() => setReady(true)} />
 *     </>
 *
 * The Gamestage loader (`Loading brand`) held over the whole screen, fixed, from
 * the first render until the game says it is ready, then faded away. Render the
 * game underneath it from the start, so its first screen is laid out at its
 * real size before anybody sees it.
 *
 * Why one screen and not a loader per stage: Mystery drew one loader while the
 * client started and another while the round loaded, in boxes of different
 * heights, so the mark jumped as one replaced the other and the card then
 * jumped again as it arrived. Fixed to the screen, nothing under it can move
 * it. Preload the mark in the page's HTML (`<link rel="preload" as="image"
 * crossorigin>`, since a mask is a CORS fetch) so it is drawn with the loader.
 */
export function GamestageLoader({ ready = false, brand = true, strings, className, ...rest }: GamestageLoaderProps) {
  const [gone, setGone] = React.useState(false)
  React.useEffect(() => {
    if (!ready) {
      setGone(false)
      return
    }
    const timer = setTimeout(() => setGone(true), LEAVE_MS)
    return () => clearTimeout(timer)
  }, [ready])
  if (gone) return null
  return (
    <div
      {...rest}
      className={['gs-loading-screen', className].filter(Boolean).join(' ')}
      data-gs-loading="screen"
      data-gs-leaving={ready ? 'true' : undefined}
      aria-hidden={ready ? 'true' : undefined}
    >
      <Loading brand={brand || true} strings={strings} />
    </div>
  )
}

/* Loading. Tokens only: no literal colour and no literal size. It fills its
   container and centres one mark, so what replaces it arrives in one step. */

.gs-loading {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  min-height: var(--gs-size-action-large);
}

.gs-loading__spinner {
  width: var(--gs-size-icon-hero);
  height: var(--gs-size-icon-hero);
  border-radius: var(--gs-radius-full);
  border: var(--gs-space-1) solid var(--gs-color-edge);
  border-top-color: var(--gs-color-interactive-solid);
  /* One turn per pulse, at the rays' constant speed curve. */
  animation: gs-loading-spin var(--gs-motion-pulse) var(--gs-motion-ease-rays) infinite;
}

.gs-loading__track {
  position: relative;
  width: min(100%, calc(var(--gs-size-action-large) * 4));
  height: var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  overflow: hidden;
}

.gs-loading__fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--gs-loading-fraction, 0.35) * 100%);
  border-radius: inherit;
  background: var(--gs-color-interactive);
  transition: width var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* No measure of progress: the fill sweeps. */
.gs-loading__track:not([style]) .gs-loading__fill {
  animation: gs-loading-sweep var(--gs-motion-pulse) var(--gs-motion-ease-pulse) infinite;
}

/* The words are for screen readers; the mark is what a sighted player reads. */
.gs-loading__label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* The Gamestage loader, Stage's own (GSUI-297): the mark afloat, the words
   under it, a track sweeping below. The float is slow and shallow on purpose:
   this is a wait, and motion that hurries reads as something being wrong. */
.gs-loading__brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--gs-space-4);
  animation: gs-loading-enter var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis) both;
}

.gs-loading__mark {
  display: block;
  width: calc(var(--gs-size-icon-hero) * 1.5);
  aspect-ratio: 1;
  background: var(--gs-color-ink);
  -webkit-mask: var(--gs-loading-mark) center / contain no-repeat;
  mask: var(--gs-loading-mark) center / contain no-repeat;
  animation: gs-loading-float var(--gs-motion-glow) var(--gs-motion-ease-glow) infinite;
}

.gs-loading__powered {
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  color: var(--gs-color-ink-secondary);
  text-align: center;
}

.gs-loading__brand .gs-loading__track {
  display: block;
  width: calc(var(--gs-size-action-large) * 3);
  height: var(--gs-space-1);
}

.gs-loading__brand .gs-loading__fill {
  width: 40%;
  background: var(--gs-color-ink);
  animation: gs-loading-sweep var(--gs-motion-pulse) var(--gs-motion-ease-pulse) infinite;
}

/* GamestageLoader: the brand loader held over the whole screen, fixed, so
   nothing laid out beneath it can move it, then faded when the game is ready.
   The fade is --gs-motion-emphasis, 200ms, which LEAVE_MS in loading.tsx
   matches. */
.gs-loading-screen {
  position: fixed;
  inset: 0;
  /* Above the nav and above a sheet (nav + 1): nothing a game draws while it
     loads should show through. */
  z-index: calc(var(--gs-layer-nav, 50) + 2);
  display: grid;
  place-items: center;
  background: var(--gs-color-background);
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-loading-screen[data-gs-leaving='true'] {
  opacity: 0;
  pointer-events: none;
}

@keyframes gs-loading-enter {
  from { opacity: 0; transform: translateY(var(--gs-space-2)); }
  to { opacity: 1; transform: none; }
}

@keyframes gs-loading-float {
  50% { transform: translateY(calc(-1 * var(--gs-space-1))); }
}

@keyframes gs-loading-spin {
  to { transform: rotate(360deg); }
}

@keyframes gs-loading-sweep {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(290%); }
}

@keyframes gs-loading-pulse {
  50% { opacity: 0.45; }
}

@media (prefers-reduced-motion: reduce) {
  .gs-loading-screen {
    transition: none;
  }
  .gs-loading__brand,
  .gs-loading__mark {
    animation: none;
  }
  .gs-loading__spinner,
  .gs-loading__brand .gs-loading__fill,
  .gs-loading__track:not([style]) .gs-loading__fill {
    animation: gs-loading-pulse var(--gs-motion-glow) var(--gs-motion-ease-glow) infinite;
  }
}
